#include <iostream>
#include <vector>

using namespace std;

int main() {
    // Read input.
    int N;
    cin >> N;
    vector<int> a(N);
    for (int i = 0; i < N; i++) {
        int tmp;
        cin >> tmp;
        a[i] = tmp;
    }
    // Start solving.
    if (N == 1 && a[0] == 0) {
        cout << "UP" << endl;
        return 0;
    }
    if (N == 1 && a[0] == 15) {
        cout << "DOWN" << endl;
        return 0;
    }
    if (N == 1 && a[0] != 0 && a[0] != 15) {
        cout << -1 << endl;
        return 0;
    }
    // From here I assume a has more than two elements.
    if (a[N-2] > a[N-1] && a[N-1] != 0) {
        cout << "DOWN" << endl;
        return 0;
    }
    if (a[N-2] < a[N-1] && a[N-1] != 15) {
        cout << "UP" << endl;
        return 0;
    }
    if (a[N-1] == 0) {
        cout << "UP" << endl;
        return 0;
    }
    if (a[N-1] == 15) {
        cout << "DOWN" << endl;
        return 0;
    }
    return 0;
}

